typedef CGAL::Alpha_shape_vertex_base_2<K> Vb;
typedef CGAL::Alpha_shape_face_base_2<K> Fb;
typedef CGAL::Triangulation_data_structure_2<Vb, Fb> Tds;
typedef CGAL::Delaunay_triangulation_2<K, Tds> Triangulation_2;
typedef CGAL::Alpha_shape_2<Triangulation_2> Alpha_shape_2;
typedef K::Point_2 CGALPoint;

std::vector<CGALPoint> cgal_points;
cgal_points.reserve(points.size());
for (const auto& p : points) {
    cgal_points.emplace_back(p.x(), p.y());
}

Alpha_shape_2 as(cgal_points.begin(), cgal_points.end(), alpha, Alpha_shape_2::REGULARIZED);
std::list<Alpha_shape_2::Vertex_handle> vertices;
as.get_alpha_shape_vertices(std::back_inserter(vertices), Alpha_shape_2::REGULAR);

std::vector<std::vector<Point2d>> components;
std::map<Alpha_shape_2::Vertex_handle, bool> visited;

for (const auto& v : vertices) {
    if (visited[v]) continue;

    std::vector<Point2d> component;
    std::queue<Alpha_shape_2::Vertex_handle> q;
    q.push(v);
    visited[v] = true;

    while (!q.empty()) {
        auto curr = q.front(); q.pop();
        component.emplace_back(curr->point().x(), curr->point().y());

        Alpha_shape_2::Vertex_circulator vc = as.incident_vertices(curr), done(vc);
        do {
            if (!as.is_infinite(vc) && !visited[vc] && 
                as.classify(vc) != Alpha_shape_2::EXTERIOR) {
                visited[vc] = true;
                q.push(vc);
            }
        } while (++vc != done);
    }

    if (component.size() >= 3) {
        components.push_back(std::move(component));
    }
}

return static_cast<int>(components.size());

